/**
 * Bulk-safe handler for ContactTrigger.
 *
 * Responsibilities (behaviour identical to the legacy inline trigger):
 *  - Before insert/update: fill blank MailingCountry from the parent Account's
 *    BillingCountry, and on insert fill blank LeadSource from the parent
 *    Account's AccountSource.
 *  - After insert: if a contact has a phone and its parent account has none,
 *    copy the phone to the account. When several contacts of the same account
 *    qualify, only the first one in trigger order sets the account phone.
 *
 * Governor budget for a batch of up to 200 contacts:
 *  - at most 1 SOQL query in the before context
 *  - at most 1 SOQL query in the after-insert context
 *  - at most 1 DML statement (the account update)
 */
public class ContactTriggerHandler {

    /**
     * Before insert / before update:
     * single query for all distinct parent accounts, then populate fields in
     * memory on Trigger.new (no DML needed in a before context).
     */
    public static void handleBefore() {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : Trigger.new) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountMap = new Map<Id, Account>(
            [SELECT Id, BillingCountry, AccountSource FROM Account WHERE Id IN :accountIds]
        );

        for (Contact c : Trigger.new) {
            Account a = accountMap.get(c.AccountId);
            if (a == null) {
                continue;
            }
            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = a.BillingCountry;
            }
            if (Trigger.isInsert && String.isBlank(c.LeadSource)) {
                c.LeadSource = a.AccountSource;
            }
        }
    }

    /**
     * After insert: copy a contact phone to its parent account when the
     * account has no phone. The shared map instance means that once the first
     * eligible contact (in trigger order) sets the account phone, later
     * contacts of the same account see a non-blank phone and are skipped.
     * One query and at most one DML statement for the whole batch.
     */
    public static void handleAfterInsert() {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : Trigger.new) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountMap = new Map<Id, Account>(
            [SELECT Id, Phone FROM Account WHERE Id IN :accountIds]
        );

        List<Account> accountsToUpdate = new List<Account>();
        for (Contact c : Trigger.new) {
            if (c.AccountId == null || String.isBlank(c.Phone)) {
                continue;
            }
            Account a = accountMap.get(c.AccountId);
            if (a == null || String.isNotBlank(a.Phone)) {
                continue;
            }
            a.Phone = c.Phone;
            accountsToUpdate.add(a);
        }
        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
```

