/**
 * Nightly purge job for FB_Integration_Log__c.
 *
 * Deletes integration logs created more than 30 days ago, except logs whose
 * Level__c is 'ERROR', which are retained until they were created more than
 * 180 days ago. Blank/DEBUG/INFO levels follow the 30-day rule.
 */
public class LogPurgeJob implements Schedulable {

    private static final Integer PAGE_SIZE = 5000;
    private static final Integer STANDARD_RETENTION_DAYS = 30;
    private static final Integer ERROR_RETENTION_DAYS = 180;
    private static final String ERROR_LEVEL = 'ERROR';

    public LogPurgeJob() {
    }

    public void execute(SchedulableContext context) {
        purgeOldLogs();
    }

    /**
     * Deletes all purgeable FB_Integration_Log__c records in pages of 5000 so
     * arbitrarily large backlogs are handled within governor limits.
     */
    public static void purgeOldLogs() {
        Date standardCutoff = Date.today() - STANDARD_RETENTION_DAYS;
        Date errorCutoff = Date.today() - ERROR_RETENTION_DAYS;

        List<FB_Integration_Log__c> logs;
        do {
            logs = [
                SELECT Id
                FROM FB_Integration_Log__c
                WHERE (COALESCE(Level__c, '') = :ERROR_LEVEL AND CreatedDate < :errorCutoff)
                   OR (COALESCE(Level__c, '') <> :ERROR_LEVEL AND CreatedDate < :standardCutoff)
                LIMIT :PAGE_SIZE
            ];
            if (!logs.isEmpty()) {
                delete logs;
            }
        } while (logs.size() == PAGE_SIZE);
    }

    /**
     * Schedules the job to run every day at 02:00 under the name
     * 'Log purge (nightly)' and returns the returned job Id.
     */
    public static Id scheduleNightly() {
        return System.schedule(
            'Log purge (nightly)',
            '0 0 2 * * ?',
            new LogPurgeJob()
        );
    }
}
