/**
 * Nightly purge job for FB_Integration_Log__c integration logs.
 *
 * Deletes logs older than 30 days, except ERROR-level logs, which are
 * retained until they are more than 180 days old.
 */
public class LogPurgeJob implements Schedulable {

    public LogPurgeJob() {}

    public void execute(SchedulableContext context) {
        purgeOldLogs();
    }

    /**
     * Deletes FB_Integration_Log__c records that are no longer needed:
     * - non-ERROR logs (including blank levels) older than 30 days
     * - ERROR logs older than 180 days
     *
     * Bulk-safe: records are fetched and deleted in chunks of 2000,
     * repeated until no eligible records remain in the transaction.
     */
    public static void purgeOldLogs() {
        final Integer batchSize = 2000;
        final Datetime nonErrorCutoff = Datetime.now().addDays(-30);
        final Datetime errorCutoff = Datetime.now().addDays(-180);

        while (true) {
            List<Id> idsToDelete = new List<Id>();
            for (FB_Integration_Log__c log : [
                SELECT Id
                FROM FB_Integration_Log__c
                WHERE ( (Level__c = NULL OR Level__c != 'ERROR') AND CreatedDate < :nonErrorCutoff )
                   OR ( Level__c = 'ERROR' AND CreatedDate < :errorCutoff )
                LIMIT :batchSize
            ]) {
                idsToDelete.add(log.Id);
            }

            if (idsToDelete.isEmpty()) {
                break;
            }
            delete idsToDelete;
        }
    }

    /**
     * Schedules the purge to run daily at 02:00.
     *
     * @return the Id of the created CronTrigger
     */
    public static Id scheduleNightly() {
        return System.schedule('Log purge (nightly)', '0 0 2 * * ?', new LogPurgeJob());
    }
}
