import { LightningElement, api } from 'lwc';

let listboxUid = 0;

export default class StatusListbox extends LightningElement {
    @api label;

    _options = [];
    _value = null;
    _activeIndex = 0;
    _uid;

    constructor() {
        super();
        listboxUid += 1;
        this._uid = `status-listbox-${listboxUid}`;
    }

    @api
    get options() {
        return this._options;
    }

    @api
    set options(value) {
        this._options = Array.isArray(value) ? value : [];
        this._syncActiveIndex();
    }

    @api
    get value() {
        return this._value;
    }

    @api
    set value(value) {
        this._value = value;
        this._syncActiveIndex();
    }

    get activeOptionId() {
        if (this._options.length === 0) {
            return null;
        }
        const index = Math.max(0, Math.min(this._activeIndex, this._options.length - 1));
        return `${this._uid}-option-${index}`;
    }

    get optionIds() {
        return this._options.map((option, index) => `${this._uid}-option-${index}`);
    }

    get selectedIndex() {
        return this._options.findIndex((option) => option.value === this._value);
    }

    handleKeydown(event) {
        const { key } = event;
        switch (key) {
            case 'ArrowDown':
                event.preventDefault();
                if (this._activeIndex < this._options.length - 1) {
                    this._activeIndex += 1;
                }
                break;
            case 'ArrowUp':
                event.preventDefault();
                if (this._activeIndex > 0) {
                    this._activeIndex -= 1;
                }
                break;
            case 'Home':
                event.preventDefault();
                this._activeIndex = 0;
                break;
            case 'End':
                event.preventDefault();
                this._activeIndex = Math.max(this._options.length - 1, 0);
                break;
            case 'Enter':
            case ' ':
                event.preventDefault();
                this._selectActiveOption();
                break;
            default:
                // Preserve default behaviour for every other key (notably Tab).
                break;
        }
    }

    handleOptionClick(event) {
        const clickedValue = event.currentTarget.dataset.value;
        const index = this._options.findIndex((option) => String(option.value) === String(clickedValue));
        if (index === -1) {
            return;
        }
        this._activeIndex = index;
        this._select(index);
    }

    _indexOfValue(value) {
        return this._options.findIndex((option) => option.value === value);
    }

    _syncActiveIndex() {
        const index = this._indexOfValue(this._value);
        this._activeIndex = index >= 0 ? index : 0;
    }

    _selectActiveOption() {
        if (this._options.length === 0) {
            return;
        }
        const index = Math.max(0, Math.min(this._activeIndex, this._options.length - 1));
        this._activeIndex = index;
        this._select(index);
    }

    _select(index) {
        const option = this._options[index];
        if (!option || option.value === this._value) {
            // Option is already selected: nothing to do, no change event.
            return;
        }
        this._value = option.value;
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value: option.value }
            })
        );
    }
}
