import { LightningElement, api, track } from 'lwc';

let instanceCount = 0;

export default class StatusListbox extends LightningElement {
    @api label;

    @track _options = [];
    @track _value = '';
    @track _activeIndex = null;
    _instanceId = 'status-listbox';

    constructor() {
        super();
        instanceCount += 1;
        this._instanceId = `status-listbox-${instanceCount}`;
    }

    @api
    get options() {
        return this._options;
    }

    @api
    set options(newOptions) {
        this._options = Array.isArray(newOptions) ? newOptions : [];
        this._revalidateActiveIndex();
    }

    @api
    get value() {
        return this._value;
    }

    @api
    set value(newValue) {
        this._value = newValue == null ? '' : newValue;
        // When the parent changes the value, the active option moves to it.
        const index = this._indexOfValue(this._value);
        if (index >= 0) {
            this._activeIndex = index;
        }
    }

    get displayOptions() {
        return this._options.map((option, index) => ({
            value: option.value,
            label: option.label,
            id: `${this._instanceId}-${index}`,
            ariaSelected: this._isSelected(option.value) ? 'true' : 'false'
        }));
    }

    get activeId() {
        const options = this.displayOptions;
        if (options.length === 0) {
            return undefined;
        }
        return options[this.activeIndex].id;
    }

    get activeIndex() {
        this._revalidateActiveIndex();
        return this._activeIndex;
    }

    handleKeydown(event) {
        const key = event.key;
        if (key === 'ArrowDown' || key === 'ArrowUp') {
            event.preventDefault();
            this._setActiveOption(this.activeIndex + (key === 'ArrowDown' ? 1 : -1));
        } else if (key === 'Home') {
            event.preventDefault();
            this._setActiveOption(0);
        } else if (key === 'End') {
            event.preventDefault();
            this._setActiveOption(this._options.length - 1);
        } else if (key === 'Enter' || key === ' ') {
            event.preventDefault();
            this._selectOption(this._options[this.activeIndex]);
        }
        // Every other key (notably Tab) keeps its default behaviour.
    }

    handleOptionClick(event) {
        const index = this._indexOfValue(event.currentTarget.dataset.value);
        if (index < 0) {
            return;
        }
        // Clicking an option makes it the active option as well.
        this._activeIndex = index;
        this._selectOption(this._options[index]);
    }

    _selectOption(option) {
        if (!option || this._isSelected(option.value)) {
            // The option was already selected: nothing is dispatched.
            return;
        }
        this._value = option.value;
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value: option.value }
            })
        );
    }

    _setActiveOption(index) {
        if (
            Number.isInteger(index) &&
            index >= 0 &&
            index < this._options.length
        ) {
            this._activeIndex = index;
        }
    }

    _revalidateActiveIndex() {
        const length = this._options.length;
        if (this._activeIndex == null) {
            // The active option starts as the selected option, or the first
            // option if nothing is selected.
            const index = this._indexOfValue(this._value);
            this._activeIndex = index >= 0 ? index : 0;
        }
        if (this._activeIndex < 0) {
            this._activeIndex = 0;
        }
        if (length > 0 && this._activeIndex >= length) {
            this._activeIndex = length - 1;
        }
    }

    _isSelected(value) {
        return String(value) === String(this._value);
    }

    _indexOfValue(value) {
        for (let i = 0; i < this._options.length; i += 1) {
            const option = this._options[i];
            if (option && String(option.value) === String(value)) {
                return i;
            }
        }
        return -1;
    }
}
