import { LightningElement, api } from 'lwc';

export default class StatusListbox extends LightningElement {
    /**
     * Accessible name of the listbox. Rendered as the aria-label of the list.
     * @type {string}
     */
    @api label = '';

    /**
     * Per-instance prefix so option ids are unique to this component instance.
     */
    _idPrefix = `status-listbox-${Math.random().toString(36).slice(2, 10)}`;

    /**
     * Options enriched with a stable id and a selected flag, as rendered.
     */
    _options = [];

    /**
     * Private reactive copy of the public value (the selected value).
     */
    _value = '';

    /**
     * Index of the active option (referenced by aria-activedescendant).
     * Null until it can be determined.
     */
    _activeIndex = null;

    @api
    get options() {
        return this._options;
    }

    set options(value) {
        this._options = (value || []).map((option, index) => ({
            value: option.value,
            label: option.label,
            id: `${this._idPrefix}-option-${index}`,
            selected: option.value === this._value
        }));
        this._syncActiveIndex();
    }

    @api
    get value() {
        return this._value;
    }

    set value(value) {
        this._value = value ?? '';
        // When the parent changes the value, the active option moves to it.
        const index = this._options.findIndex((option) => option.value === this._value);
        if (index >= 0) {
            this._activeIndex = index;
        }
        // Keep the selected flags in sync with the new value.
        this._options = this._options.map((option) => ({
            ...option,
            selected: option.value === this._value
        }));
    }

    /**
     * Id of the active option, referenced by aria-activedescendant.
     * Undefined while there is no active option (the attribute is removed).
     */
    get activeOptionId() {
        if (this._activeIndex === null) {
            return undefined;
        }
        const option = this._options[this._activeIndex];
        return option ? option.id : undefined;
    }

    /**
     * The active option starts as the selected option, or the first option
     * if nothing is selected. Only applied while the active option is not
     * yet in range (initial state, or after the option list changes).
     */
    _syncActiveIndex() {
        if (
            this._activeIndex !== null &&
            this._activeIndex >= 0 &&
            this._activeIndex < this._options.length
        ) {
            return;
        }
        const selectedIndex = this._options.findIndex(
            (option) => option.value === this._value
        );
        this._activeIndex = selectedIndex >= 0 ? selectedIndex : 0;
    }

    /**
     * Moves the active option by one, clamped at the list bounds (no
     * wrap-around). Moving the active option does not change the selection.
     */
    _moveActiveOption(delta) {
        if (this._options.length === 0) {
            return;
        }
        const current = this._activeIndex === null ? 0 : this._activeIndex;
        const next = Math.min(Math.max(current + delta, 0), this._options.length - 1);
        this._activeIndex = next;
    }

    /**
     * Keyboard support following the WAI-ARIA listbox pattern. Only the six
     * listed keys are handled; every other key (notably Tab) keeps its
     * default behaviour.
     */
    handleListKeyDown(event) {
        switch (event.key) {
            case 'ArrowDown':
                event.preventDefault();
                this._moveActiveOption(1);
                break;
            case 'ArrowUp':
                event.preventDefault();
                this._moveActiveOption(-1);
                break;
            case 'Home':
                event.preventDefault();
                this._activeIndex = 0;
                break;
            case 'End':
                event.preventDefault();
                this._activeIndex = this._options.length - 1;
                break;
            case 'Enter':
            case ' ':
                event.preventDefault();
                this._selectOption(this._options[this._activeIndex]);
                break;
            default:
                // Keep the default behaviour (e.g. Tab).
                break;
        }
    }

    /**
     * Clicking an option selects it and makes it the active option.
     */
    handleOptionClick(event) {
        const index = this._options.findIndex(
            (option) => option.id === event.currentTarget.id
        );
        if (index === -1) {
            return;
        }
        this._activeIndex = index;
        this._selectOption(this._options[index]);
    }

    /**
     * Selects the given option. Dispatches a change event with
     * detail { value } unless the option was already selected.
     */
    _selectOption(option) {
        if (!option || option.value === this._value) {
            // Not selectable, or already selected: nothing to do.
            return;
        }
        this.value = option.value;
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value: option.value }
            })
        );
    }
